// ------------------------------------------------------------------ entry

/**
 * Every flag this tool answers to.
 *
 * Kept as data and checked, because the alternative is what was here: any
 * argument beginning with a dash went into a set nobody validated, so a typo
 * was indistinguishable from silence. `unmark clean report.docx --in-plce`
 * exited 0 having written nothing, and a CI step reading `unmark clean x
 * --in-place || fail` passed while the file sat untouched. main.test.ts named
 * this hazard and patched the one case that had bitten; this closes the class.
 */
const KNOWN_FLAGS = new Set([
  '--json',
  '--in-place',
  '--paranoid',
  '--confusables',
  '--typography',
  '--humanise',
  '--plain',
  '--force',
  '--print-prompt',
  '--model',
  '--attempts',
  '--against',
  '--format',
  '--lang',
  '--min-score',
  '--pages',
  '--source',
  '--top',
  '--register',
  '--apply',
  '--rewrite',
  '--version',
  '-V',
  '--help',
  '-h',
])

export async function main(argv: readonly string[]): Promise<number> {
  const flags = new Set(argv.filter((arg) => arg.startsWith('-') && arg !== '-'))

  // `--model=x` carries its value in the same token, so the name is what is
  // checked. A bare `--` is the conventional end-of-options marker and is not
  // a flag this tool has anything to say about.
  const unknown = [...flags]
    .map((flag) => flag.split('=')[0] as string)
    .filter((flag) => flag !== '--' && !KNOWN_FLAGS.has(flag))
  if (unknown.length > 0) {
    process.stderr.write(
      `unmark: unknown option${unknown.length === 1 ? '' : 's'} ${unknown.join(', ')}\n\n` +
        'Run `unmark --help` for the list. Nothing was read and nothing was written.\n',
    )
    return 2
  }

  /** `--model gpt-x` and `--model=gpt-x` both work; a missing value is undefined. */
  const value = (name: string): string | undefined => {
    const inline = argv.find((arg) => arg.startsWith(`${name}=`))
    if (inline) return inline.slice(name.length + 1)
    const at = argv.indexOf(name)
    const next = at === -1 ? undefined : argv[at + 1]
    return next && !next.startsWith('-') ? next : undefined
  }

  // A flag's value is not a positional argument — consumed by INDEX, not by
  // value. Consuming by value deleted the file argument whenever it happened to
  // equal a flag's value, so `unmark verify x.md --against x.md` lost its
  // target, fell back to reading stdin, and hung forever with no output.
  // Verifying a file against itself is the first thing anyone tries.
  const consumed = new Set<number>()
  for (const name of [
    '--model',
    '--attempts',
    '--against',
    '--format',
    '--lang',
    '--min-score',
    '--pages',
    '--source',
    '--top',
    '--register',
    '--apply',
  ]) {
    const at = argv.indexOf(name)
    const next = at === -1 ? undefined : argv[at + 1]
    if (at !== -1 && next && !next.startsWith('-')) consumed.add(at + 1)
  }
  const positional = argv.filter(
    (arg, at) => (!arg.startsWith('-') || arg === '-') && !consumed.has(at),
  )

  if (flags.has('--version') || flags.has('-V')) {
    process.stdout.write(`${VERSION}\n`)
    return 0
  }
  if (positional.length === 0 || flags.has('--help') || flags.has('-h')) {
    process.stdout.write(USAGE)
    return 0
  }

  // A flag whose value is not a number is a mistake, and it used to be an
  // expensive silent one: `Number('abc')` is NaN, `--attempts 0` is 0, both are
  // falsy, both were dropped by the spread below, and both came out as the
  // default of 3. Someone writing `--attempts 0` to mean "just check, spend
  // nothing" got three paid calls.
  const attempts = value('--attempts')
  if (attempts !== undefined && !/^[1-9]\d*$/.test(attempts)) {
    process.stderr.write(`unmark: --attempts needs a whole number of tries, not "${attempts}"\n`)
    return 2
  }

  // detect's three values, checked the same way: a wrong one is named and
  // nothing is read, rather than quietly falling back to a default. A flag
  // with no value at all is the same mistake: `--format` alone used to print
  // text, which is the one format the caller had not asked for.
  for (const name of [
    '--format',
    '--lang',
    '--min-score',
    '--pages',
    '--source',
    '--top',
    '--register',
    '--apply',
  ]) {
    if (flags.has(name) && value(name) === undefined) {
      process.stderr.write(`unmark: ${name} needs a value\n`)
      return 2
    }
  }
  const format = value('--format')
  if (format !== undefined && !['text', 'md', 'json'].includes(format)) {
    process.stderr.write(`unmark: --format takes text, md or json, not "${format}"\n`)
    return 2
  }
  const lang = value('--lang')
  if (lang !== undefined && !['fr', 'en', 'auto'].includes(lang)) {
    process.stderr.write(`unmark: --lang takes fr, en or auto, not "${lang}"\n`)
    return 2
  }
  const minScore = value('--min-score')
  if (
    minScore !== undefined &&
    (!/^(?:0(?:\.\d+)?|1(?:\.0+)?|\.\d+)$/.test(minScore) || Number(minScore) > 1)
  ) {
    process.stderr.write(`unmark: --min-score takes a number from 0 to 1, not "${minScore}"\n`)
    return 2
  }

  const top = value('--top')
  if (top !== undefined && !/^[1-9]\d*$/.test(top)) {
    process.stderr.write(`unmark: --top needs a whole number of sentences, not "${top}"\n`)
    return 2
  }
  const register = value('--register')
  if (register !== undefined && !['general', 'academic'].includes(register)) {
    process.stderr.write(`unmark: --register takes general or academic, not "${register}"\n`)
    return 2
  }

  const options: Options = {
    json: flags.has('--json'),
    inPlace: flags.has('--in-place'),
    paranoid: flags.has('--paranoid'),
    confusables: flags.has('--confusables'),
    printPrompt: flags.has('--print-prompt'),
    force: flags.has('--force'),
    ...(value('--model') ? { model: value('--model') as string } : {}),
    ...(attempts ? { attempts: Number(attempts) } : {}),
    ...(value('--against') ? { against: value('--against') as string } : {}),
    ...(format ? { format: format as 'text' | 'md' | 'json' } : {}),
    ...(lang ? { lang: lang as 'fr' | 'en' | 'auto' } : {}),
    ...(minScore === undefined ? {} : { minScore: Number(minScore) }),
    ...(value('--pages') ? { pages: value('--pages') as string } : {}),
    ...(value('--source') ? { source: value('--source') as string } : {}),
    ...(top ? { top: Number(top) } : {}),
    ...(register ? { register: register as 'general' | 'academic' } : {}),
    ...(value('--apply') ? { apply: value('--apply') as string } : {}),
    rewrite: flags.has('--rewrite'),
    // --plain is one name for the pair, defined once in the core so the page's
    // button and this flag cannot drift into two different presets.
    typography: flags.has('--typography') || (flags.has('--plain') && PLAIN.typography === true),
    humanise: flags.has('--humanise') || (flags.has('--plain') && PLAIN.humanise === true),
  }

  const [command, target = '-'] = positional

  try {
    switch (command) {
      case 'inspect': {
        return await commandInspect(target, options)
      }
      case 'clean': {
        return await commandClean(target, options)
      }
      case 'decode': {
        return await commandDecode(target, options)
      }
      case 'brief': {
        return await commandBrief(target)
      }
      case 'verify': {
        return await commandVerify(target, options)
      }
      case 'rewrite': {
        return await commandRewrite(target, options)
      }
      case 'detect': {
        return await commandDetect(target, options)
      }
      case 'sweep': {
        return await commandSweep(target, options)
      }
      case 'audit': {
        return await commandAudit(target === '-' ? '.' : target, options)
      }
      default: {
        process.stderr.write(`unmark: unknown command "${command}"\n\nRun \`unmark --help\`.\n`)
        return 2
      }
    }
  } catch (error) {
    process.stderr.write(`unmark: ${error instanceof Error ? error.message : String(error)}\n`)
    return 2
  }
}

// The deterministic core: everything unmark can prove it did.
//
// Nothing here may import from `node:` or touch the DOM. That constraint is the
// whole architecture — it is what lets this exact code run inside the page and
// inside the CLI without a second implementation drifting away from the first.
// Pixel work (canvas, WebGPU, wasm) lives in src/image and is browser-only by
// nature; the CLI says so rather than pretending otherwise.

export { VERSION } from './version.ts'

export * from './report.ts'
export * from './text/index.ts'
export * from './container/index.ts'

// A static server over `dist`, so what the tests drive is what ships.
//
// Not the dev server, and the difference matters: the build injects the
// Content-Security-Policy, and a layout that only works because a blocked font
// quietly fell back is broken in production and fine in development. The same
// applies to the service worker, which is only emitted by a build.
//
// Extracted from scripts/shoot.mjs so the screenshot script, the Playwright
// web server and the specs all serve bytes one way rather than three.
//
// Plain ESM rather than TypeScript because Playwright starts it with bare
// `node`, and adding a loader to the toolchain to serve five hundred bytes of
// static files would be a poor trade.

import { createServer } from 'node:http'
import { readFile } from 'node:fs/promises'
import { extname, join, normalize } from 'node:path'

export const BASE = '/unmark/'

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript',
  '.mjs': 'text/javascript',
  '.css': 'text/css',
  '.json': 'application/json',
  '.webmanifest': 'application/manifest+json',
  '.woff2': 'font/woff2',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.pdf': 'application/pdf',
  // Served with the right type so the runtime uses streaming instantiation,
  // which is the path production takes.
  '.wasm': 'application/wasm',
  '.onnx': 'application/octet-stream',
}

/**
 * Serve `dist` on `port`.
 *
 * `sw.js` goes out with `Service-Worker-Allowed` so the worker may claim the
 * whole base path, which is what the offline test needs and what GitHub Pages
 * does by default.
 */
export async function serveDist(port, dist = 'dist') {
  const server = createServer(async (request, response) => {
    const url = new URL(request.url ?? '/', `http://localhost:${port}`)
    let path = url.pathname.startsWith(BASE)
      ? url.pathname.slice(BASE.length)
      : url.pathname.slice(1)
    if (path === '' || !extname(path)) path = 'index.html'

    try {
      const safe = normalize(path).replace(/^(\.\.[/\\])+/, '')
      const body = await readFile(join(dist, safe))
      response.writeHead(200, {
        'content-type': TYPES[extname(path)] ?? 'application/octet-stream',
        'service-worker-allowed': BASE,
        // No caching, so a reload inside a test sees the file rather than a
        // copy the browser decided to keep.
        'cache-control': 'no-store',
      })
      response.end(body)
    } catch {
      response.writeHead(404).end('not found')
    }
  })

  await new Promise((resolve) => server.listen(port, resolve))

  return {
    url: `http://localhost:${port}${BASE}`,
    close: () =>
      new Promise((resolve, reject) =>
        server.close((error) => (error ? reject(error) : resolve())),
      ),
  }
}

// Which handler a file goes to, decided by what it is rather than what it is called.
//
// Sniffing beats the extension every time: a .jpg that is really a PNG is
// common enough that trusting the name would hand the wrong parser a file it
// will quietly mangle. The name is only consulted for the text formats, where
// there are no magic bytes to read and Markdown and HTML genuinely look alike.

import { byPosition, type Finding } from '../report.ts'
import { cleanText, type TextOptions } from '../text/unicode.ts'
import { stegoFindings } from '../text/stego.ts'
import { rebase, splice } from '../text/frame.ts'
import { cleanPng, sniffPng } from './png.ts'
import { cleanJpeg, sniffJpeg } from './jpeg.ts'
import { cleanWebp, sniffWebp } from './webp.ts'
import { cleanGif, sniffGif } from './gif.ts'
import { cleanPdf, sniffPdf } from './pdf/index.ts'
import { cleanIsobmff, sniffIsobmff } from './isobmff/index.ts'
import { cleanZipDocument } from './zipdoc.ts'
import { ooxmlFlavour, readZip, sniffZip, zipDocumentKind } from './zip.ts'
import { cleanHtml, cleanMarkdown, cleanSvg, type TextCleanResult } from './markup.ts'
import { decodeUtf8, encode, type ContainerResult, type MediaEntry } from './types.ts'

import type { ContainerFormat } from './formats.ts'
export type { ContainerFormat } from './formats.ts'

/**
 * Options that are about the container rather than about the text inside it.
 *
 * One field so far. `force` exists because a signed PDF is refused by default —
 * any edit voids the signature — and the only honest way to offer the other
 * choice is to make the user ask for it by name.
 */
export interface ContainerOptions {
  force?: boolean
}

export interface FileResult extends ContainerResult {
  format: ContainerFormat
  /** True when the output is meant to be read as text rather than saved as bytes. */
  textual: boolean
}

/** Formats whose provenance lives in markup rather than in a binary structure. */
const MARKUP: Partial<Record<ContainerFormat, (text: string) => TextCleanResult>> = {
  SVG: cleanSvg,
  HTML: cleanHtml,
  Markdown: cleanMarkdown,
}

const extensionOf = (name?: string) => name?.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1] ?? ''

/**
 * Whether these bytes are text at all.
 *
 * The text path decodes UTF-8, edits a string, and encodes it back. That round
 * trip is lossless for text and destructive for anything else: every byte that
 * is not valid UTF-8 comes back as U+FFFD, three bytes wide. A file format
 * nobody here recognises used to fall straight into that path, so
 * `unmark clean mystery.bin --in-place` corrupted the file and reported zero
 * findings — the tool doing damage while saying it had found nothing.
 *
 * A strict decode is the test. A NUL byte is checked separately because it is
 * valid UTF-8 and still means binary in every practical case.
 */
function looksLikeText(bytes: Uint8Array): boolean {
  if (bytes.subarray(0, 8192).includes(0)) return false
  try {
    new TextDecoder('utf-8', { fatal: true }).decode(bytes)
    return true
  } catch {
    return false
  }
}

/** Text formats have no magic bytes, so this is content first and name second. */
function sniffText(text: string, name?: string): ContainerFormat {
  const head = text.slice(0, 1024).trimStart().toLowerCase()
  const extension = extensionOf(name)

  if (head.startsWith('<svg') || (head.startsWith('<?xml') && text.includes('<svg'))) return 'SVG'
  if (head.startsWith('<!doctype html') || head.startsWith('<html')) return 'HTML'
  if (extension === 'svg') return 'SVG'
  if (extension === 'html' || extension === 'htm') return 'HTML'
  if (extension === 'md' || extension === 'markdown') return 'Markdown'
  if (text.startsWith('---\n') || text.startsWith('---\r\n')) return 'Markdown'
  return 'Text'
}

async function sniffBinary(bytes: Uint8Array): Promise<ContainerFormat | undefined> {
  if (sniffPng(bytes)) return 'PNG'
  if (sniffJpeg(bytes)) return 'JPEG'
  if (sniffWebp(bytes)) return 'WebP'
  if (sniffGif(bytes)) return 'GIF'
  if (sniffPdf(bytes)) return 'PDF'

  // ISOBMFF is checked after the still formats above because its `ftyp` box
  // starts at offset 4, not 0 — there is no leading magic to collide with.
  const isobmff = sniffIsobmff(bytes)
  if (isobmff) return isobmff

  if (sniffZip(bytes)) {
    try {
      const entries = await readZip(bytes)
      const kind = zipDocumentKind(entries)
      // One handler covers all three OOXML applications; the flavour is only
      // what the report calls the file.
      if (kind === 'ooxml') return ooxmlFlavour(entries)
      if (kind === 'odf') return 'ODT'
      if (kind === 'epub') return 'EPUB'
    } catch {
      // A zip we cannot read is not a document we can clean. Fall through and
      // report it as unknown rather than returning half a file.
      return 'unknown'
    }
    return 'unknown'
  }

  return undefined
}

/**
 * Strip a file's provenance metadata.
 *
 * Text formats get two passes: the markup rules that know about generator tags
 * and metadata blocks, then the invisible-character pass — an HTML page can
 * carry a zero-width watermark in its prose just as easily as a .txt can.
 *
 * Every finding in the report addresses the file as it arrived. The markup pass
 * reports there natively; the invisible-character pass runs on the markup pass's
 * output and is read back through the frame that pass returns. Before that,
 * the two sets of offsets differed by whatever the markup pass had removed and
 * were sorted together as though they did not.
 */
export async function cleanContainer(
  bytes: Uint8Array,
  name?: string,
  options?: TextOptions & ContainerOptions,
): Promise<FileResult> {
  const binary = await sniffBinary(bytes)

  if (binary && binary !== 'unknown') {
    const result = await cleanBinary(bytes, binary, options)
    return { ...result, format: binary, textual: false }
  }
  // An unreadable zip, or bytes that are not text, are both handed back exactly
  // as they arrived. Returning half a file, or a file with every invalid byte
  // replaced, is worse than saying the format is not recognised.
  if (binary === 'unknown' || !looksLikeText(bytes)) {
    return { output: bytes, findings: [], preserved: [], format: 'unknown', textual: false }
  }

  const text = decodeUtf8(bytes)
  const format = sniffText(text, name)
  const markup = MARKUP[format]

  const stage1 = markup ? markup(text) : { output: text, findings: [] as Finding[], splices: [] }
  const stage2 = cleanText(stage1.output, options)
  const frame = splice(text, stage1.splices).frame

  return {
    output: encode(stage2.output),
    findings: [
      ...stage1.findings,
      ...stage2.findings.map((finding) => rebase(frame, finding)),
      ...stegoFindings(text),
    ].sort(byPosition),
    preserved: stage2.preserved.map((finding) => rebase(frame, finding)),
    format,
    textual: true,
  }
}

function cleanBinary(bytes: Uint8Array, format: ContainerFormat, options?: ContainerOptions) {
  switch (format) {
    case 'PNG': {
      return cleanPng(bytes)
    }
    case 'JPEG': {
      return cleanJpeg(bytes)
    }
    case 'WebP': {
      return cleanWebp(bytes)
    }
    case 'GIF': {
      return cleanGif(bytes)
    }
    case 'PDF': {
      return cleanPdf(bytes, options?.force === true ? { force: true } : {})
    }
    case 'HEIC':
    case 'AVIF':
    case 'MP4': {
      return cleanIsobmff(bytes)
    }
    default: {
      return cleanZipDocument(bytes)
    }
  }
}

/**
 * A file's text and its text format, or `undefined` when it is not text.
 *
 * For the commands that read prose rather than containers. A PDF or a DOCX
 * has text inside it, but getting it out faithfully is its own job; reading
 * the bytes as UTF-8 would score the file's structure as if it were writing.
 */
export async function readTextual(
  bytes: Uint8Array,
  name?: string,
): Promise<{ text: string; format: ContainerFormat } | undefined> {
  const binary = await sniffBinary(bytes)
  if (binary !== undefined || !looksLikeText(bytes)) return undefined
  const text = decodeUtf8(bytes)
  return { text, format: sniffText(text, name) }
}

/** Report a file's marks without changing it. */
export async function inspectContainer(
  bytes: Uint8Array,
  name?: string,
  options?: TextOptions & ContainerOptions,
): Promise<{
  format: ContainerFormat
  findings: Finding[]
  preserved: Finding[]
  textual: boolean
  coverage?: string[]
  media?: MediaEntry[]
}> {
  const { format, findings, preserved, textual, coverage, media } = await cleanContainer(
    bytes,
    name,
    options,
  )
  return {
    format,
    findings: [...findings, ...preserved].sort(byPosition),
    preserved,
    textual,
    ...(coverage ? { coverage } : {}),
    ...(media ? { media } : {}),
  }
}

export {
  cleanGif,
  cleanHtml,
  cleanJpeg,
  cleanMarkdown,
  cleanPdf,
  cleanPng,
  cleanSvg,
  cleanWebp,
  cleanZipDocument,
  readZip,
}
export { writeZip } from './zip.ts'
export type { ContainerResult, MediaEntry, TextCleanResult }

// The text half of the core, as one surface.
//
// The three modules underneath answer different questions and are deliberately
// separate — what is in here, what does it say, and what does the prose look
// like — but a caller almost always wants all three at once, in one ordered
// report. This is that report, and it is what both the page and the CLI call.

import { byPosition, type CleanResult, type Finding } from '../report.ts'
import { cleanText, inspectText, isLoadBearing, type TextOptions } from './unicode.ts'
import { decodeStego, encodeStego, stegoFindings, type StegoDecoding } from './stego.ts'
import { analyzeStyle, stylometryFindings, type StyleReport } from './stylometry.ts'
import { identity, splice } from './frame.ts'
import { tidySeam } from './humanise.ts'

export {
  analyzeStyle,
  cleanText,
  decodeStego,
  encodeStego,
  inspectText,
  isLoadBearing,
  stegoFindings,
  stylometryFindings,
}
export { distinctSignals, MIN_PARAGRAPHS, MIN_SENTENCES, MIN_WORDS } from './stylometry.ts'
export { humanise } from './humanise.ts'
export { normaliseTypography } from './typography.ts'
export { cleanProvenance } from './provenance.ts'
export { blocksOf, paragraphsOf, protectedMask } from './regions.ts'
export { detectSpaceCadence } from './stego.ts'
export type { StegoDecoding, StyleReport, TextOptions }
export type { StyleLayer, StyleMetric } from './stylometry.ts'
export type { StegoScheme } from './stego.ts'
// The authorship assessment is deliberately not re-exported here. The page
// imports this module on first load, and the assessment's catalogues and
// language models would ride along with it; import ./authorship/index.ts
// directly, lazily in the page. scripts/check-imports.mjs holds that line.

/**
 * The one-button preset.
 *
 * Marks come off whatever the options say — that is what a clean is. This turns
 * on the two passes that are about how the writing *reads*, which are off by
 * default because they rewrite the author's prose. Naming it once here keeps
 * the page's button and the CLI's `--plain` from drifting into two presets.
 *
 * It does not remove a statistical watermark, and every surface that offers it
 * has to say so on the same screen.
 */
export const PLAIN: TextOptions = { typography: true, humanise: true }

export interface TextReport {
  /** Everything found, in document order: carriers, payloads, style tells. */
  findings: Finding[]
  /** Carriers matched but deliberately kept, with the reason on each. */
  preserved: Finding[]
  /**
   * The stripped document, from the same pass the findings came out of.
   *
   * Carried on the report rather than left to the caller, because the caller
   * that wanted both ran `cleanText` a second time to get it — and `cleanText`
   * is the expensive half. Measured on 139k characters of ordinary prose: 361
   * ms of the report's 422, paid twice on every rebuild. `useDeferredValue`
   * does not help with that; a single synchronous pass is uninterruptible
   * however it is scheduled.
   */
  cleaned: CleanResult<string>
  /** Payloads recovered from the carriers, most plausible first. */
  stego: StegoDecoding[]
  style: StyleReport
}

/**
 * Rewrite exactly these spans of `text`, and nothing else.
 *
 * The counterpart to the options on `cleanText`: those say "every em dash in
 * this document", and this says "that one". It takes the document as it
 * arrived, because that is the frame every text finding is now in — the caller
 * passes the string it showed the reader, never the cleaned one.
 *
 * Applying all of one pass's findings gives that pass's own output, and there
 * is a test holding the two together. That equality is the point: an interface
 * offering both a toggle and a per-finding button must not have them disagree
 * about the same character.
 *
 * A finding with no `replacement` is skipped rather than throwing. Nothing
 * should be offering to apply one, but a core function that explodes on a
 * report-only finding is a trap laid for the next caller.
 */
export function applyFindings(text: string, findings: readonly Finding[]): string {
  const editable = findings.filter((f) => f.replacement !== undefined && f.scope !== 'document')
  if (editable.length === 0) return text

  const ordered = [...editable].sort(byPosition)
  let stage = splice(
    text,
    ordered.map((f) => ({
      start: f.offset,
      end: f.offset + f.length,
      to: f.replacement as string,
    })),
    identity(text.length),
  )

  // Only a deleted phrase gets its seam tidied, and the kind is what says so.
  // `humanise` closes the gap a removed phrase leaves — a doubled space, a
  // stranded comma, a sentence now opening in lower case — and applying one of
  // its findings has to do the same or the button and the toggle produce two
  // different documents. A deleted zero-width carrier gets none of it: the
  // spaces either side of it were already the author's.
  const seams: number[] = []
  let drift = 0
  for (const finding of ordered) {
    const replacement = finding.replacement as string
    const at = finding.offset - drift + replacement.length
    drift += finding.length - replacement.length
    if (finding.kind === 'ai_phrase' && replacement.length === 0) seams.push(at)
  }

  for (let index = seams.length - 1; index >= 0; index -= 1) {
    stage = tidySeam(stage.text, stage.frame, seams[index] as number)
  }

  return stage.text
}

/** Read a document without changing it. */
export function inspectTextDocument(text: string, options?: TextOptions): TextReport {
  const cleaned = cleanText(text, options)
  const { findings, preserved } = cleaned
  return {
    findings: [...findings, ...preserved, ...stegoFindings(text), ...stylometryFindings(text)].sort(
      byPosition,
    ),
    preserved,
    cleaned,
    stego: decodeStego(text),
    style: analyzeStyle(text),
  }
}

/**
 * Strip a document, and decode what was in it first.
 *
 * The decode happens against the *original* text: once the carriers are gone
 * there is nothing left to read, so a clean pass that did not decode first
 * would destroy the evidence it was asked to find.
 */
export function cleanTextDocument(
  text: string,
  options?: TextOptions,
): CleanResult<string> & { stego: StegoDecoding[]; style: StyleReport } {
  const stego = decodeStego(text)
  const result = cleanText(text, options)
  return { ...result, stego, style: analyzeStyle(text) }
}

// ISOBMFF: HEIC, AVIF, MP4 and MOV are one format wearing four brands.
//
// This file is the policy — what counts as provenance, what is refused, and how
// a rewritten tree is put back together. The format itself is next door: the box
// walker and the two size escapes in `boxes.ts`, the item machinery a HEIC hangs
// its picture on in `heif.ts`, the tags and timestamps a movie carries in
// `movie.ts`.
//
// Deleting a box is never the whole job. Every ancestor's size field counts the
// bytes it contains, so a four-byte tag removed six levels down changes six
// sizes. Worse, two tables hold absolute byte offsets into the file: `stco` and
// `co64` point at the media chunks inside `mdat`, and `iloc` points at every
// item of a HEIC or an AVIF. Remove anything ahead of them and both are wrong.
// So this pass records every range it cut and re-points those tables afterwards.
//
// Where that cannot be done safely it does nothing at all. A fragmented file
// carries offsets in `moof`, `sidx`, `saio` and `mfra` that this pass does not
// rewrite, so such a file comes back untouched with the reason attached. An
// honest refusal beats a plausible video that no longer plays.
//
// What survives is as deliberate as what goes. `ipco` holds the picture's
// properties and `ipma` associates them *by index*, so dropping one property box
// would silently renumber every association after it — `colr`, `ispe`, `pixi`,
// `av1C` and `hvcC` all stay, and `mdat` is never rewritten except to cut out
// the bytes of an item that is going away. `colr` is still reported: an embedded
// ICC profile outlives an EXIF strip and its description names whoever wrote
// the file.

import { byPosition, type Finding } from '../../report.ts'
import { ascii, concat, decodeUtf8, readU32, snippet, type ContainerResult } from '../types.ts'
import { withC2pa } from '../c2pa.ts'
import {
  collect,
  containerChildren,
  headerLength,
  readBox,
  rewriteHeader,
  writeUint,
  type Box,
  type Found,
  type Range,
} from './boxes.ts'
import { planItems, repointIloc } from './heif.ts'
import { blankTimestamps, classifyTag, parseKeys, repointChunks } from './movie.ts'

// ----------------------------------------------------------------- sniffing

const AVIF_BRANDS = new Set(['avif', 'avis'])
const HEIC_BRANDS = new Set(['heic', 'heix', 'mif1', 'msf1'])
const MP4_BRANDS = new Set(['isom', 'mp42', 'qt  ', 'M4V '])

/**
 * Which of the three a file is, from the `ftyp` box every one of them opens with.
 *
 * The compatible brands matter as much as the major one, and AVIF is tested
 * first because an AVIF declares `mif1` alongside `avif` — HEIC's brand. Asking
 * "is it HEIC?" first would answer yes for every AVIF in existence.
 */
export function sniffIsobmff(bytes: Uint8Array): 'HEIC' | 'AVIF' | 'MP4' | undefined {
  if (bytes.length < 12 || ascii(bytes, 4, 4) !== 'ftyp') return undefined

  const declared = readU32(bytes, 0) >>> 0
  const end = declared >= 16 && declared <= bytes.length ? declared : Math.min(bytes.length, 12)
  const brands = [ascii(bytes, 8, 4)]
  for (let at = 16; at + 4 <= end; at += 4) brands.push(ascii(bytes, at, 4))

  if (brands.some((brand) => AVIF_BRANDS.has(brand))) return 'AVIF'
  if (brands.some((brand) => HEIC_BRANDS.has(brand))) return 'HEIC'
  if (brands.some((brand) => MP4_BRANDS.has(brand))) return 'MP4'
  return undefined
}

// ----------------------------------------------------------- what comes out

/** C2PA's own box UUID, from the C2PA specification's BMFF binding. */
const C2PA_UUID = 'd8fec3d61b0e483c92975828877ec481'
/** Adobe's UUID for an XMP packet carried in an ISOBMFF file. */
const XMP_UUID = 'be7acfcb97a942e89c71999491e3afac'

/**
 * Structures whose byte offsets this pass does not rewrite.
 *
 * `moof` fragments carry a base data offset, `sidx` indexes segments by size
 * from its own end, `saio` points at per-sample auxiliary data and `mfra`
 * indexes fragments by absolute offset. Correcting all four means understanding
 * far more of the file than a metadata strip needs to, so their presence turns
 * a pass that would move bytes into a refusal instead.
 */
const FRAGILE = new Set(['moof', 'sidx', 'saio', 'mfra'])

/** Printable runs inside a binary blob, so a report can quote what named the writer. */
function printableRuns(data: Uint8Array, minimum = 6): string[] {
  const runs: string[] = []
  let current = ''
  for (const byte of data) {
    if (byte >= 0x20 && byte < 0x7f) current += String.fromCharCode(byte)
    else {
      if (current.length >= minimum) runs.push(current)
      current = ''
    }
  }
  if (current.length >= minimum) runs.push(current)
  return runs
}

/**
 * The JUMBF store inside C2PA's `uuid` box.
 *
 * The C2PA BMFF binding puts a full-box header, a NUL-terminated purpose
 * string and, for `manifest`, a 64-bit Merkle offset in front of the store.
 */
function c2paPayload(bytes: Uint8Array, box: Box): Uint8Array {
  const purposeStart = box.body + 4
  const nul = bytes.indexOf(0, purposeStart)
  if (nul === -1 || nul >= box.end) return bytes.subarray(box.end, box.end)
  const purpose = ascii(bytes, purposeStart, nul - purposeStart)
  const start = nul + 1 + (purpose === 'manifest' ? 8 : 0)
  return bytes.subarray(Math.min(start, box.end), box.end)
}

/**
 * What a box is, or undefined to copy it through untouched.
 *
 * A finding that carries `preserved` is one to report and leave alone; anything
 * else is on its way out. `colr` is the only entry matched in order to be kept:
 * removing it changes how the picture renders, but when it holds a full ICC
 * profile rather than a handful of coefficients, that profile's description
 * names whoever wrote the file and outlives every EXIF strip.
 */
function classify(
  bytes: Uint8Array,
  box: Box,
  parent: string,
  keys: readonly string[],
): Finding | undefined {
  const at = { offset: box.start, length: box.end - box.start }

  if (box.type === 'uuid') {
    if (box.uuid === C2PA_UUID) {
      return withC2pa(
        { kind: 'c2pa', verdict: 'confirmed', ...at, label: 'uuid — C2PA manifest' },
        c2paPayload(bytes, box),
      )
    }
    if (box.uuid === XMP_UUID) {
      const packet = decodeUtf8(bytes.subarray(box.body, box.end))
      const tool = /<(?:xmp:CreatorTool|tiff:Software|dc:creator)>([^<]+)</i.exec(packet)?.[1]
      return {
        kind: 'xmp',
        verdict: 'probable',
        ...at,
        label: 'uuid — XMP packet',
        ...(tool ? { evidence: snippet(tool) } : {}),
      }
    }
    return undefined
  }

  // JUMBF is the box C2PA signs its manifest into when it is not using a UUID.
  if (box.type === 'jumb') {
    return withC2pa(
      { kind: 'c2pa', verdict: 'confirmed', ...at, label: 'jumb — JUMBF / C2PA provenance' },
      bytes.subarray(box.start, box.end),
    )
  }

  if (box.type === 'colr') {
    const profile = ascii(bytes, box.body, 4)
    const strings = printableRuns(bytes.subarray(box.body + 4, box.end)).slice(0, 3)
    return {
      kind: 'generator_tag',
      verdict: 'informational',
      ...at,
      label: `colr — colour profile (${profile})`,
      ...(strings.length > 0 ? { evidence: snippet(strings.join(' · ')) } : {}),
      preserved: 'a colour profile, not provenance — removing it changes the rendering',
    }
  }

  return classifyTag(bytes, box, parent, keys)
}

// ------------------------------------------------------------- the rebuild

interface Plan {
  bytes: Uint8Array
  findings: Finding[]
  preserved: Finding[]
  /** Boxes to remove outright, by the offset their header starts at. */
  drop: Set<number>
  /** Boxes to emit as different bytes: a pruned `iloc`, `ipma` or reference entry. */
  replace: Map<number, Uint8Array>
  /** Item payload ranges to cut out of whichever leaf contains them. */
  holes: Range[]
  /** The key names each `meta` box declares, by that box's own offset. */
  keysByMeta: Map<number, string[]>
  /** Every range actually removed from the original file, in original coordinates. */
  removed: Range[]
  /** How many holes the rebuild found a home for, so an orphan can be caught. */
  holesCut: number
  /** Set to the reason when the file has to come back untouched. */
  blocker: string
}

interface Rebuilt {
  parts: Uint8Array[]
  length: number
  /** Boxes emitted, so `iinf` can rewrite the count it keeps of its children. */
  count: number
  /**
   * Whether anything in here came out different.
   *
   * Not the same question as "did the length change": a blanked timestamp is
   * the same number of bytes, and a parent that compared lengths would decide
   * nothing had happened and hand back the original bytes, throwing the edit
   * away at every level on the way up.
   */
  changed: boolean
}

function rebuild(
  plan: Plan,
  start: number,
  end: number,
  parent: string,
  keys: readonly string[],
): Rebuilt {
  const bytes = plan.bytes
  const parts: Uint8Array[] = []
  let length = 0
  let count = 0
  let changed = false
  const push = (part: Uint8Array) => {
    parts.push(part)
    length += part.length
  }

  let at = start
  while (at < end) {
    const box = readBox(bytes, at, end)
    if (!box || box.end <= at) break

    if (plan.drop.has(box.start)) {
      plan.removed.push({ start: box.start, end: box.end })
      changed = true
      at = box.end
      continue
    }

    const finding = classify(bytes, box, parent, keys)
    if (finding) {
      if (finding.preserved) {
        plan.preserved.push(finding)
      } else {
        plan.findings.push(finding)
        plan.removed.push({ start: box.start, end: box.end })
        changed = true
        at = box.end
        continue
      }
    }

    const replacement = plan.replace.get(box.start)
    if (replacement) {
      // A pruned table loses bytes from the middle, but nothing in the file
      // points into one, so for the purpose of shifting later offsets the loss
      // is booked at the box's tail. What matters is only how many bytes are
      // gone before whatever comes next.
      plan.removed.push({ start: box.start + replacement.length, end: box.end })
      push(replacement)
      changed = true
      count += 1
      at = box.end
      continue
    }

    const children = containerChildren(bytes, box)
    if (children === undefined) {
      const rewritten = rewriteLeaf(plan, box)
      push(rewritten ?? bytes.subarray(box.start, box.end))
      if (rewritten) changed = true
    } else {
      // A `meta` box brings its own key table, which its `ilst` sibling names
      // its tags by. Anything else passes down whatever it was given.
      const inner = rebuild(
        plan,
        children,
        box.end,
        box.type,
        box.type === 'meta' ? (plan.keysByMeta.get(box.start) ?? keys) : keys,
      )
      if (inner.changed) {
        const prefix = bytes.slice(box.body, children)
        if (box.type === 'iinf') writeUint(prefix, 4, prefix.length - 4, inner.count)
        push(rewriteHeader(bytes, box, headerLength(box) + prefix.length + inner.length))
        push(prefix)
        for (const part of inner.parts) push(part)
        changed = true
      } else {
        // Nothing below this box came out different, so hand back the original
        // bytes. That is what makes a file with nothing to strip come out byte
        // for byte the same, including any 64-bit or run-to-the-end size field.
        push(bytes.subarray(box.start, box.end))
      }
    }

    count += 1
    at = box.end
  }

  // A truncated or unparseable tail is still the user's file: copy it rather
  // than silently returning something shorter.
  if (at < end) push(bytes.subarray(at, end))
  return { parts, length, count, changed }
}

/**
 * A leaf that has to come out different, or nothing when it does not.
 *
 * Two reasons it might: an item's bytes sit inside it and are being cut out, or
 * it is a header whose timestamps are being blanked. The second keeps its length.
 */
function rewriteLeaf(plan: Plan, box: Box): Uint8Array | undefined {
  const bytes = plan.bytes
  const holes = plan.holes.filter((hole) => hole.start >= box.body && hole.end <= box.end)

  if (holes.length === 0) {
    const stamps = blankTimestamps(bytes, box)
    if (!stamps) return undefined
    plan.findings.push(stamps.finding)
    return stamps.patched
  }

  const pieces: Uint8Array[] = []
  let cursor = box.body
  for (const hole of holes) {
    pieces.push(bytes.subarray(cursor, hole.start))
    cursor = hole.end
    plan.removed.push(hole)
    plan.holesCut += 1
  }
  pieces.push(bytes.subarray(cursor, box.end))

  const body = concat(pieces)
  return concat([rewriteHeader(bytes, box, headerLength(box) + body.length), body])
}

/** Walk the finished file and move every stored offset to where its bytes went. */
function repoint(plan: Plan, out: Uint8Array, start: number, end: number): void {
  let at = start
  while (at < end && !plan.blocker) {
    const box = readBox(out, at, end)
    if (!box || box.end <= at) break
    if (box.type === 'stco' || box.type === 'co64') {
      plan.blocker = repointChunks(out, box, plan.removed)
    } else if (box.type === 'iloc') {
      plan.blocker = repointIloc(out, box, plan.removed)
    } else {
      const children = containerChildren(out, box)
      if (children !== undefined) repoint(plan, out, children, box.end)
    }
    at = box.end
  }
}

// ------------------------------------------------------------------- entry

/** Everything that was going to be removed, reported as kept, with the reason. */
function refuse(plan: Plan, reason: string): ContainerResult {
  const headline: Finding = {
    kind: 'doc_property',
    verdict: 'informational',
    offset: 0,
    length: 0,
    label: 'File returned unchanged — it could not be rewritten safely',
    evidence: reason,
    preserved: reason,
  }
  // Only the findings that were on their way out get the refusal attached.
  // Anything already in `preserved` was never going to be removed, and saying
  // it survived for this reason would be the wrong explanation.
  const preserved: Finding[] = [headline, ...plan.preserved]
  for (const finding of plan.findings) {
    preserved.push({ ...finding, preserved: `not removed: ${reason}` })
  }
  return { output: plan.bytes, findings: [], preserved: preserved.sort(byPosition) }
}

export function cleanIsobmff(bytes: Uint8Array): ContainerResult {
  const found: Found[] = []
  collect(bytes, 0, bytes.length, '', 0, found)
  const items = planItems(bytes, found)

  const plan: Plan = {
    bytes,
    findings: items.findings,
    preserved: items.preserved,
    drop: items.drop,
    replace: items.replace,
    holes: items.holes,
    keysByMeta: new Map(),
    removed: [],
    holesCut: 0,
    blocker: items.blocker,
  }
  if (plan.blocker) return refuse(plan, plan.blocker)

  for (const entry of found) {
    if (entry.box.type === 'keys') {
      plan.keysByMeta.set(entry.parentStart, parseKeys(bytes, entry.box))
    }
  }

  const rebuilt = rebuild(plan, 0, bytes.length, '', [])

  if (!rebuilt.changed) {
    // Nothing came out different, so the answer is the input itself — byte for
    // byte, including any 64-bit or run-to-the-end size field.
    return { output: bytes, findings: [], preserved: plan.preserved.sort(byPosition) }
  }

  // Only a rewrite that moves bytes can invalidate a stored offset. Blanking a
  // timestamp in place cannot, so it stays available in files this would refuse.
  if (plan.removed.length > 0) {
    if (found.some((entry) => FRAGILE.has(entry.box.type))) {
      return refuse(
        plan,
        'this file is fragmented or indexed, and carries byte offsets in boxes this pass ' +
          'does not rewrite (moof, sidx, saio, mfra)',
      )
    }
    if (plan.holesCut !== plan.holes.length) {
      return refuse(
        plan,
        "an item's bytes did not sit inside a single box, so they were left alone",
      )
    }
  }

  const output = concat(rebuilt.parts)
  if (plan.removed.length > 0) {
    plan.removed.sort((a, b) => a.start - b.start)
    repoint(plan, output, 0, output.length)
    if (plan.blocker) return refuse(plan, plan.blocker)
  }

  return {
    output,
    findings: plan.findings.sort(byPosition),
    preserved: plan.preserved.sort(byPosition),
  }
}

// The PDF handler's front door.
//
// This directory was one file until the rebuild landed. The split is by stage,
// not by size: lex reads objects, xref says where they are, objects resolves
// the graph, write serialises it back, clean decides what to remove and
// whether it dares. Each stage is testable against the format alone, which is
// the only reason a PDF writer is a defensible thing to have written by hand.

import { startsWith } from '../types.ts'

export const sniffPdf = (bytes: Uint8Array): boolean => startsWith(bytes, [0x25, 0x50, 0x44, 0x46]) // %PDF

export { bytePass, cleanPdf, type PdfCleanOptions } from './clean.ts'

// Was this written by a model? An assessment, located, never a proof.
//
// The pipeline, each stage its own module and its own test:
//
//   segment     sentences of unsealed prose, with lines and columns
//   route       French or English, paragraph by paragraph
//   scan        every catalogue pattern once, filed under its sentence
//   forensics   technical marks from the existing passes
//   measure     five features per sentence
//   spans       a score and a band per sentence
//   signals     one number per habit family
//   verdict     three guards, and an abstention below 150 words
//   report      the same answer as data, Markdown and findings
//
// Pure and synchronous: no `node:`, no DOM, no network. A caller that can run
// a model hands its number in through `external`.

import type { Finding } from '../../report.ts'
import { VERSION } from '../../version.ts'
import { protectedMask } from '../regions.ts'
import { lineIndex } from '../lines.ts'
import { analyzeStyle } from '../stylometry.ts'
import { CALIBRATION, type Calibration } from './calibration.ts'
import { entriesFor, measure, scan, wordReuse, type Hit, type Register } from './features.ts'
import { UNWEIGHTED } from './catalogue/index.ts'
import { recaps } from './recap.ts'
import { blocksOf } from '../regions.ts'
import { technicalMarks } from './forensics.ts'
import { locator, type Layout } from './locate.ts'
import {
  DISCLAIMER,
  excerptOf,
  NOT_EVIDENCE,
  type AuthorshipFinding,
  type AuthorshipReport,
  type DocumentSource,
  type FileMark,
  type LanguageBlock,
  type Location,
  type Severity,
  type UnsupportedSegment,
} from './report.ts'
import { route, type LangOption, type Routing } from './route.ts'
import { segment, type Lang, type Segmentation } from './segment.ts'
import { builtInSignals, fromExternal, type EvidenceLabel, type ExternalSignal } from './signals.ts'
import { scoreSentences } from './spans.ts'
import { decide, MIN_WORDS, type AuthorshipVerdict, type Confidence } from './verdict.ts'

export interface DetectOptions {
  /** Force a language instead of detecting it per paragraph. */
  lang?: LangOption
  /** The container format, as `inspect` names it: `Text`, `Markdown`, `HTML`. */
  format?: string
  /** Signals computed outside the core, averaged in with their own weights. */
  external?: readonly ExternalSignal[]
  /** For the evaluation harness; everything else uses the shipped one. */
  calibration?: Calibration
  /** List every sentence in `spans`, not only those in a band. For evaluation. */
  allSpans?: boolean
  /**
   * List the catalogue matches the tier rules did not count too, marked
   * `counted: false`. For `sweep`, which lists every habit however isolated.
   */
  allFindings?: boolean
  /** Paragraphs, sections and pages of the document the text came from. */
  layout?: Layout
  /** Marks of the file the text came from, from `inspect`. */
  fileMarks?: readonly FileMark[]
  /** Assess the whole text as one block, even when it changes language. */
  singleBlock?: boolean
  /** What the text was read from, carried into the report as it is. */
  document?: DocumentSource
  /** Also read the formulas of a register, tier 3: `academic`. */
  register?: Register
}

/** Markers of academic prose, per thousand words, above which the text reads as academic. */
const ACADEMIC_CUES =
  /\[\d{1,3}(?:\s*[,–-]\s*\d{1,3})*\]|\bet al\.|\b(?:95\s?%\s?CI|IC\s?(?:à\s)?95\s?%)|\bp\s?[<=>]\s?0[.,]\d/gu
const ACADEMIC_RATE = 2

/** The register a text reads as, from its citations and statistics. */
export function readsAcademic(text: string, words: number): boolean {
  if (words === 0) return false
  const cues = [...text.matchAll(ACADEMIC_CUES)].length
  return (cues / words) * 1000 >= ACADEMIC_RATE
}

/**
 * The marks of a container that belong in an authorship report.
 *
 * Everything confirmed, plus provenance whatever its verdict: a C2PA manifest
 * or a generator tag says which tool touched the file. Author names, editing
 * time and camera EXIF are left out: every .docx has them, and listing them
 * beside a verdict about writing would make an ordinary file look marked.
 */
export function fileMarksFrom(findings: readonly Finding[]): FileMark[] {
  return findings
    .filter(
      (f) =>
        f.refusal !== true &&
        (f.verdict === 'confirmed' ||
          ((f.kind === 'c2pa' || f.kind === 'generator_tag') && f.verdict === 'probable')),
    )
    .map((f) => ({
      origin: 'file' as const,
      kind: f.kind,
      verdict: f.verdict,
      label: f.label,
      ...(f.where ? { where: f.where } : {}),
      ...(f.evidence ? { evidence: f.evidence } : {}),
      ...(f.placement ? { placement: f.placement } : {}),
      ...(f.c2pa ? { c2pa: { origin: f.c2pa.origin, statement: f.c2pa.statement } } : {}),
    }))
}

/** Overwrite with spaces, newlines kept, so every offset and line still holds. */
const blank = (match: string) => match.replaceAll(/[^\n]/gu, ' ')

/** Elements whose content is not prose: dropped whole, like a fenced block. */
const NOT_PROSE = /<(script|style|pre|code|template|svg)\b[^>]{0,500}>[\s\S]*?<\/\1\s*>/giu
/** Tags that start or end a block; they become paragraph breaks. */
const BLOCK_TAG =
  /<\/?(?:p|div|h[1-6]|li|ul|ol|br|hr|section|article|header|footer|main|nav|aside|blockquote|table|tr|td|th|dl|dt|dd|figure|figcaption|title|head|body|html)\b[^>]{0,500}>/giu
const ANY_TAG = /<!--[\s\S]*?-->|<[!/]?[a-z][^>]{0,500}>/giu

/**
 * An HTML page as prose, at the same length as the page.
 *
 * Every tag is overwritten rather than removed, so a passage found here is
 * found at the same offset in the page, and lines are counted on the page
 * itself. A block tag turns into a paragraph break: two <p> on one line are
 * two paragraphs, which is what the tier-2 rule counts within.
 */
function htmlAsProse(html: string): string {
  return html
    .replaceAll(NOT_PROSE, blank)
    .replaceAll(BLOCK_TAG, (tag) => `\n\n${' '.repeat(Math.max(0, tag.length - 2))}`)
    .replaceAll(ANY_TAG, blank)
}

const severityOf = (hit: Hit): Severity =>
  hit.entry.category === 'residue'
    ? 'high'
    : UNWEIGHTED.has(hit.entry.category) || hit.entry.category === 'register'
      ? 'low'
      : hit.entry.category === 'formatting' || hit.entry.tier === 1
        ? 'medium'
        : 'low'

const labelOf = (hit: Hit): EvidenceLabel =>
  hit.entry.category === 'residue' || hit.entry.category === 'formatting'
    ? 'CHAT_RESIDUE'
    : 'STYLE_HEURISTIC'

/** The sentence around an offset, or failing that its line. */
function contextOf(text: string, seg: Segmentation, hit: Hit): [number, number] {
  const sentence = seg.sentences[hit.sentence]
  if (sentence) return [sentence.start, sentence.end]
  const from = text.lastIndexOf('\n', hit.start - 1) + 1
  const newline = text.indexOf('\n', hit.end)
  return [from, newline === -1 ? text.length : newline]
}

/** A run of paragraphs shorter than this does not make a block of its own. */
const MIN_RUN_WORDS = 60

interface Run {
  lang: Lang | 'other'
  first: number
  last: number
  words: number
  /** Words per language, for the run's majority once short runs are merged in. */
  byLang: Map<Lang | 'other', number>
}

/**
 * Consecutive paragraphs in one language, short interruptions absorbed.
 *
 * A keyword line or a one-line quotation in the other language would
 * otherwise cut an article into three blocks too short to assess. A run under
 * MIN_RUN_WORDS joins the run before it (or after it, at the start), and the
 * merged run takes the language most of its words are in.
 */
function languageRuns(routing: Routing, seg: Segmentation): Run[] {
  const words = seg.blocks.map(() => 0)
  for (const sentence of seg.sentences)
    words[sentence.paragraphIndex] = (words[sentence.paragraphIndex] ?? 0) + sentence.words

  // A paragraph too short to identify on its own is routed with the
  // document's language, but it is no evidence of where a block starts: it
  // joins the run it sits in.
  let runs: Run[] = []
  let neutral: { first: number; words: number } | undefined
  seg.blocks.forEach((_, index) => {
    const count = words[index] ?? 0
    if (count === 0) return
    const detected = routing.detected[index]
    const last = runs.at(-1)
    if (detected === undefined) {
      if (last) {
        last.last = index
        last.words += count
      } else neutral = { first: neutral?.first ?? index, words: (neutral?.words ?? 0) + count }
      return
    }
    const lang: Lang | 'other' = detected === 'fr' || detected === 'en' ? detected : 'other'
    if (last && last.lang === lang) {
      last.last = index
      last.words += count
      last.byLang.set(lang, (last.byLang.get(lang) ?? 0) + count)
    } else {
      runs.push({
        lang,
        first: neutral?.first ?? index,
        last: index,
        words: count + (neutral?.words ?? 0),
        byLang: new Map([[lang, count]]),
      })
      neutral = undefined
    }
  })
  if (neutral) {
    const lang = routing.document === 'und' ? 'other' : routing.document
    runs.push({
      lang,
      first: neutral.first,
      last: seg.blocks.length - 1,
      words: neutral.words,
      byLang: new Map([[lang, neutral.words]]),
    })
  }

  for (let changed = true; changed && runs.length > 1;) {
    changed = false
    const at = runs.findIndex((run) => run.words < MIN_RUN_WORDS)
    if (at === -1) break
    const run = runs[at] as Run
    const into = runs[at > 0 ? at - 1 : at + 1] as Run
    into.first = Math.min(into.first, run.first)
    into.last = Math.max(into.last, run.last)
    into.words += run.words
    for (const [lang, count] of run.byLang)
      into.byLang.set(lang, (into.byLang.get(lang) ?? 0) + count)
    into.lang = [...into.byLang.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? into.lang
    runs.splice(at, 1)
    changed = true
    // Two neighbours that now share a language are one run.
    const merged: Run[] = []
    for (const next of runs) {
      const previous = merged.at(-1)
      if (previous && previous.lang === next.lang) {
        previous.last = next.last
        previous.words += next.words
        for (const [lang, count] of next.byLang)
          previous.byLang.set(lang, (previous.byLang.get(lang) ?? 0) + count)
      } else merged.push(next)
    }
    runs = merged
  }
  return runs
}

/** Everything outside `[start, end)` blanked, offsets and lines kept. */
const only = (text: string, start: number, end: number) =>
  blank(text.slice(0, start)) + text.slice(start, end) + blank(text.slice(end))

const CONFIDENCE_RANK: Record<Confidence, number> = { low: 0, medium: 1, high: 2 }

/**
 * The document's verdict from its blocks' verdicts.
 *
 * The score is the word-weighted mean of the assessed blocks' scores. The
 * guards hold block by block: `likely_ai` needs a block that is itself
 * `likely_ai`, and "few signals" needs every assessed block to say so.
 */
function combineBlocks(
  blocks: readonly LanguageBlock[],
  thresholds: { human: number; ai: number; humanReachable: boolean },
  guarded: boolean,
): Pick<AuthorshipReport, 'verdict' | 'score' | 'confidence'> | undefined {
  const assessed = blocks.filter((b) => b.score !== null && b.lang !== 'other')
  if (assessed.length < 2) return undefined
  const words = assessed.reduce((sum, b) => sum + b.words, 0)
  const score = assessed.reduce((sum, b) => sum + (b.score as number) * b.words, 0) / words
  let verdict: AuthorshipVerdict = 'uncertain'
  if (score >= thresholds.ai && assessed.some((b) => b.verdict === 'likely_ai'))
    verdict = 'likely_ai'
  else if (
    thresholds.humanReachable &&
    score < thresholds.human &&
    !guarded &&
    assessed.every((b) => b.verdict === 'likely_human')
  )
    verdict = 'likely_human'
  const confidence = assessed.reduce<Confidence>(
    (low, b) => (CONFIDENCE_RANK[b.confidence] < CONFIDENCE_RANK[low] ? b.confidence : low),
    'high',
  )
  return { verdict, score: Math.round(score * 1000) / 1000, confidence }
}

export function detectAuthorship(input: string, options: DetectOptions = {}): AuthorshipReport {
  const calibration = options.calibration ?? CALIBRATION
  const text = options.format === 'HTML' ? htmlAsProse(input) : input

  // Lines and columns always address the input as given, not its prose view.
  const seg = segment(text, protectedMask(text), lineIndex(input))
  const routing = route(text, seg, options.lang ?? 'auto')
  const register = options.register ?? 'general'
  const hits = scan(text, seg, options.format, register)
  const marks = technicalMarks(input)
  const scored = scoreSentences(seg, measure(text, seg, hits, marks), hits)
  const style = analyzeStyle(text)
  const lang = routing.document === 'und' ? 'en' : routing.document
  const fileMarks = [...(options.fileMarks ?? [])]
  const where = options.layout ? locator(text, options.layout) : () => undefined
  const located = (start: number, end?: number) => {
    const location = where(start, end)
    return location ? { location } : {}
  }

  // The forensic signal reads the prose. When the file carries marks of its
  // own, its line says so rather than "no technical mark" beside a verdict
  // held at uncertain by those very marks.
  const filed = (signal: ReturnType<typeof builtInSignals>[number]) =>
    signal.id === 'forensic' && fileMarks.length > 0
      ? {
          ...signal,
          detail: `${signal.value === 0 ? 'nothing in the prose itself, no chat residue and no hidden character' : signal.detail}; the file carries ${fileMarks.length} mark${fileMarks.length === 1 ? '' : 's'} of its own (see File marks)`,
        }
      : signal
  const signals = [
    ...builtInSignals(
      { words: seg.words, lang, spans: scored, hits, marks, style, reuse: wordReuse(text, seg) },
      calibration,
    ).map(filed),
    ...(options.external ?? []).map(fromExternal),
  ]

  const counted = hits.filter((hit) => hit.counted)
  const residue = counted.some((hit) => hit.entry.category === 'residue')
  // Guard B reads the file's marks too: a confirmed manifest on an embedded
  // image says nothing about the prose, but "few signals" is still not a thing
  // to say about a file carrying one.
  const technical = marks.length > 0 || fileMarks.some((mark) => mark.verdict === 'confirmed')
  const result = decide({
    words: seg.words,
    unsupported:
      routing.unsupportedShare > 0.5 || (routing.document === 'und' && seg.words >= MIN_WORDS),
    signals,
    residue,
    technical,
    calibration,
  })
  const thresholds = {
    human: result.human,
    ai: calibration.thresholds.ai,
    humanReachable: result.humanReachable,
  }

  const listedHits = options.allFindings === true ? hits : counted
  const findings: AuthorshipFinding[] = listedHits.map((hit) => {
    const at = seg.index.locate(hit.start)
    const [from, to] = contextOf(text, seg, hit)
    return {
      id: `${hit.entry.id}@${hit.start}`,
      patternId: hit.entry.id,
      category: hit.entry.category,
      tier: hit.entry.tier,
      start: hit.start,
      end: hit.end,
      line: at.line,
      col: at.col,
      excerpt: excerptOf(text, hit.start, hit.end, from, to),
      reason: hit.entry.reason,
      fixHint: hit.entry.fixHint,
      evidenceLabel: labelOf(hit),
      severity: severityOf(hit),
      ...(hit.counted ? {} : { counted: false }),
      ...located(hit.start, hit.end),
    }
  })

  // Language blocks. One block is the document; several are each assessed on
  // their own, and the document's verdict becomes their combination.
  const runs = options.singleBlock === true ? [] : languageRuns(routing, seg)
  const blocks: LanguageBlock[] = runs.map((run) => {
    const start = seg.blocks[run.first]?.start ?? 0
    const end = seg.blocks[run.last]?.end ?? text.length
    const base = {
      lang: run.lang,
      start,
      end,
      line: seg.index.locate(start).line,
      endLine: seg.index.locate(end).line,
      words: run.words,
      ...(where(start) ? { location: where(start) as Location } : {}),
      ...(where(Math.max(start, end - 1))
        ? { endLocation: where(Math.max(start, end - 1)) as Location }
        : {}),
    }
    if (runs.length === 1) {
      return {
        ...base,
        verdict: result.verdict,
        score: result.score,
        confidence: result.confidence,
      }
    }
    if (run.lang === 'other' || run.words < MIN_WORDS) {
      return {
        ...base,
        verdict: 'insufficient_evidence' as const,
        score: null,
        confidence: 'low' as const,
        abstainReason:
          run.lang === 'other' ? ('unsupported_language' as const) : ('too_short' as const),
      }
    }
    const { layout: _layout, ...rest } = options
    const own = detectAuthorship(only(input, start, end), {
      ...rest,
      lang: run.lang,
      singleBlock: true,
    })
    return {
      ...base,
      verdict: own.verdict,
      score: own.score,
      confidence: own.confidence,
      ...(own.abstainReason ? { abstainReason: own.abstainReason } : {}),
    }
  })
  const combined =
    result.verdict === 'insufficient_evidence' && result.abstainReason === 'too_short'
      ? undefined
      : combineBlocks(blocks, thresholds, residue || technical)

  const unsupported: UnsupportedSegment[] = []
  seg.blocks.forEach((block, index) => {
    const detected = routing.detected[index]
    if (!detected || detected === 'fr' || detected === 'en') return
    const own = seg.sentences.filter((s) => s.paragraphIndex === index)
    const count = own.reduce((sum, s) => sum + s.words, 0)
    if (count === 0) return
    unsupported.push({
      lang: detected,
      words: count,
      line: seg.index.locate(block.start).line,
      excerpt: excerptOf(text, block.start, block.end, block.start, block.end),
      ...located(block.start, block.end),
    })
  })

  // The formulas of a register, found alone, are named as what they are.
  const isolated = new Map<string, { sample: string; count: number }>()
  for (const hit of hits) {
    if (hit.entry.category !== 'register' || hit.counted) continue
    const phrase = text.slice(hit.start, hit.end).replaceAll(/\s+/gu, ' ').toLowerCase()
    const entry = isolated.get(hit.entry.id) ?? { sample: phrase, count: 0 }
    entry.count += 1
    isolated.set(hit.entry.id, entry)
  }
  const notEvidence =
    isolated.size === 0
      ? NOT_EVIDENCE
      : [
          ...NOT_EVIDENCE,
          `Formulas of the academic register, each on its own here and so not counted: ${[...isolated.values()].map((e) => `“${e.sample}”${e.count > 1 ? ` ×${e.count}` : ''}`).join(', ')}.`,
        ]

  const langs = new Set<string>(['any', ...routing.paragraphs.filter(Boolean)] as string[])
  const read = entriesFor(register).filter((entry) => langs.has(entry.lang))
  const coverage = {
    register,
    academicCues: readsAcademic(text, seg.words),
    patterns: read.length,
    matched: new Set(hits.map((hit) => hit.entry.id)).size,
    counted: new Set(hits.filter((hit) => hit.counted).map((hit) => hit.entry.id)).size,
  }

  const headings = blocksOf(text)
    .filter((block) => block.kind === 'heading')
    .map((block) => ({
      start: block.start,
      title: text
        .slice(block.start, block.end)
        .replace(/^#+\s*/u, '')
        .trim(),
    }))
  const sectionOf = (offset: number, paragraph: number): string => {
    if (options.layout) return where(offset)?.section ?? '(before the first heading)'
    const heading = headings.findLast((h) => h.start <= offset)
    return heading?.title ?? `¶${paragraph + 1}`
  }
  const loops = options.singleBlock
    ? []
    : recaps(text, seg, sectionOf, options.layout ? '(before the first heading)' : undefined).map(
        (recap) => ({
          ...recap,
          occurrences: recap.occurrences.map((o) => ({
            ...o,
            line: seg.index.locate(o.start).line,
            ...located(o.start, o.end),
          })),
        }),
      )

  // Too little text because the file would not give it up — encrypted, or no
  // page decoded — is not a short text, and the reader is told which.
  const document = options.document
  const unreadable =
    result.abstainReason === 'too_short' &&
    document !== undefined &&
    (document.encrypted === true ||
      (document.pages !== undefined &&
        document.pages > 0 &&
        (document.unreadablePages?.length ?? 0) === document.pages))
  const abstainReason = unreadable ? 'unreadable' : result.abstainReason

  return {
    schemaVersion: 1,
    engine: { name: 'unmark', version: VERSION },
    calibration: { id: calibration.id, calibrated: calibration.calibrated, date: calibration.date },
    verdict: combined?.verdict ?? result.verdict,
    score: combined?.score ?? result.score,
    confidence: combined?.confidence ?? result.confidence,
    ...(abstainReason && !combined ? { abstainReason } : {}),
    language: {
      document: routing.document,
      unsupportedShare: Math.round(routing.unsupportedShare * 1000) / 1000,
      unsupported,
    },
    blocks,
    words: seg.words,
    sentences: seg.sentences.length,
    thresholds,
    signals,
    spans: scored
      .filter((span) => options.allSpans === true || span.band !== 'none')
      .map((span) => ({
        start: span.start,
        end: span.end,
        line: span.line,
        col: span.col,
        endLine: span.endLine,
        words: span.words,
        score: span.score,
        band: span.band,
        lowConfidence: span.lowConfidence,
        reasons: span.reasons,
        excerpt: excerptOf(text, span.start, span.end, span.start, span.end),
        ...(span.lang ? { lang: span.lang } : {}),
        ...located(span.start, span.end),
      })),
    findings,
    technicalMarks: marks.map((mark) => ({
      ...mark,
      ...seg.index.locate(mark.offset),
      ...located(mark.offset),
    })),
    fileMarks,
    ...(options.document
      ? {
          document: {
            ...options.document,
            ...(options.layout?.pages
              ? {
                  placed: options.layout.paragraphs.filter(
                    (p) => where(p.start, p.end)?.page !== undefined,
                  ).length,
                }
              : {}),
          },
        }
      : {}),
    recaps: loops,
    coverage,
    style,
    notEvidence,
    disclaimer: DISCLAIMER,
  }
}

